        /* We found a common prefix. Look forward as long as
         * there are entries that share the common prefix */
        for (i = homing; i < tree->entries.size; ++i) {
                entry = git_array_get(tree->entries, i);

                if (homing_search_cmp(&ksearch, entry) < 0)
