}

int git_blob__parse_raw(void *_blob, const char *data, size_t size)
{
        git_blob *blob = (git_blob *) _blob;
        assert(blob);
        blob->raw = 1;
        blob->data.raw.data = data;
        blob->data.raw.size = size;
        return 0;
}

int git_blob__parse(void *_blob, git_odb_object *odb_obj)
{
